  public enum Frequency {
    /// <summary>
    /// Undefined frequency. To be used when the frequency of an event is unknown. 
    /// </summary>
    [pbr::OriginalName("FREQ_UNDEFINED")] FreqUndefined = 0,
    /// <summary>
    /// One event by year 
    /// </summary>
    [pbr::OriginalName("FREQ_YEARLY")] FreqYearly = 1,
    /// <summary>
    /// One event every half-year 
    /// </summary>
    [pbr::OriginalName("FREQ_HALF_YEARLY")] FreqHalfYearly = 2,
    /// <summary>
    /// One event every four months 
    /// </summary>
    [pbr::OriginalName("FREQ_QUADRI_MONTHLY")] FreqQuadriMonthly = 3,
    /// <summary>
    /// One event every quarter 
    /// </summary>
    [pbr::OriginalName("FREQ_QUARTERLY")] FreqQuarterly = 4,
    /// <summary>
    /// One event every two months 
    /// </summary>
    [pbr::OriginalName("FREQ_BI_MONTHLY")] FreqBiMonthly = 6,
    /// <summary>
    /// One event every month 
    /// </summary>
    [pbr::OriginalName("FREQ_MONTHLY")] FreqMonthly = 12,
    /// <summary>
    /// One event every day 
    /// </summary>
    [pbr::OriginalName("FREQ_DAILY")] FreqDaily = 365,
  }

